const COPA_MASTER={"tagline":"Mucho más que una playa.","intro":"Copacabana puede parecer sencilla desde fuera: una playa, un calçadão y edificios frente al Atlántico. Pero detrás de esa imagen hay más de un siglo de transformación urbana, arquitectura, música, literatura, vida residencial y pequeñas historias escondidas entre sus calles. Para entender Copacabana de verdad, hay que alejarse algunas cuadras del mar de vez en cuando.","doors":[["📖","Historia"],["🗺️","Entiende el barrio"],["🏛️","Arquitectura"],["🎵","Música"],["🤫","Historias secretas"],["🇧🇷","Vida carioca"]],"timeline":[{"era":"Antes del gran barrio","title":"Sacopenapã y la pequeña Copacabana","text":"Antes de convertirse en uno de los nombres más reconocibles de Brasil, esta franja entre morros y océano estaba lejos del centro urbano. La memoria de la antigua igrejinha de Nossa Senhora de Copacabana quedó ligada al promontorio donde después se levantaría el Forte."},{"era":"1892","title":"El túnel cambia la historia","text":"La apertura del Túnel Velho ayudó a romper el aislamiento de la zona y aceleró su conexión con el resto de Río."},{"era":"1906","title":"Las ondas llegan al paseo","text":"La primera versión del mosaico ondulado de piedras portuguesas fue ejecutada en 1906. El diseño original antecede a Roberto Burle Marx."},{"era":"1908–1914","title":"Nace una fortificación moderna","text":"El Forte de Copacabana fue construido en el promontorio donde estaba la antigua iglesia, reforzando la defensa de la entonces capital brasileña."},{"era":"1922","title":"Los 18 del Forte","text":"La rebelión de julio de 1922 convirtió el Forte y la Avenida Atlântica en escenario de uno de los episodios políticos y militares más recordados de la Primera República."},{"era":"1923","title":"Copacabana Palace","text":"La inauguración del Copacabana Palace consolidó la imagen de una nueva orla sofisticada y turística. El proyecto de Joseph Gire se convirtió en una referencia arquitectónica y urbana."},{"era":"1930–1950","title":"Art Déco y ciudad vertical","text":"Edificios residenciales, hoteles, cines, bares y nuevas formas de vivir transformaron rápidamente el barrio. Para descubrir esa Copacabana todavía basta caminar mirando hacia arriba."},{"era":"1950–1960","title":"Noches, música y una nueva imagen de Río","text":"Copacabana se volvió escenario de boates, samba-jazz y encuentros musicales. La historia de la bossa nova está conectada a esta geografía nocturna, aunque su universo se extiende por otros barrios de la Zona Sul."},{"era":"1970–1974","title":"La gran reforma de la orla","text":"Con la ampliación de la Avenida Atlântica, Roberto Burle Marx reformuló y expandió el paisajismo del calçadão, preservando la idea de las ondas y sumando grandes composiciones gráficas."},{"era":"Hoy","title":"Una ciudad dentro de la ciudad","text":"Copacabana sigue mezclando postal internacional y barrio residencial: playa, supermercados, padarias, edificios históricos, jubilados, deportistas, turistas, trabajadores y vida cotidiana conviven a pocas cuadras."}],"microzones":[{"name":"Posto 2 · Lido","fit":"Práctico para Lido, Cardeal Arcoverde, hoteles y conexión con Leme.","vibe":"movimiento + turismo"},{"name":"Posto 3","fit":"Zona central para quien quiere tener buena parte de Copacabana a distancia caminable.","vibe":"central + intenso"},{"name":"Posto 4","fit":"Equilibrio entre playa, comercio, Siqueira Campos y vida cotidiana.","vibe":"equilibrado + residencial"},{"name":"Posto 5","fit":"Muy práctico para Cantagalo, restaurantes y conexión hacia Posto 6 e Ipanema.","vibe":"local + conectado"},{"name":"Posto 6","fit":"Forte, pescadores, Drummond y algunas de las imágenes clásicas del extremo sur de la playa.","vibe":"historia + fotografía"},{"name":"Bairro Peixoto","fit":"Para bajar el ritmo y descubrir una Copacabana interior, residencial y menos obvia.","vibe":"tranquilo + local"}],"architecture":[{"title":"Copacabana Palace","text":"Inaugurado en 1923 y proyectado por Joseph Gire. Su presencia ayudó a definir la imagen turística de la nueva Avenida Atlântica."},{"title":"Edifício Guahy","text":"Proyecto de 1932 de Ricardo Buffa, uno de los ejemplos protegidos del Art Déco residencial del barrio."},{"title":"Calçadão","text":"Las ondas aparecen antes de Burle Marx. Su intervención de los años 1970 amplió el paseo y creó una composición paisajística mucho mayor."},{"title":"Mira arriba","text":"Parte de la mejor Copacabana no está a nivel de los ojos: portales, coronamientos, geometrías Art Déco y detalles de edificios sobreviven entre fachadas contemporáneas."}],"secrets":["El dibujo ondulado del calçadão no fue inventado por Burle Marx: la primera versión se instaló en 1906.","Antes del Forte existía en el promontorio una pequeña iglesia ligada al nombre Copacabana.","Bairro Peixoto parece otro barrio, pero forma parte de Copacabana y conserva una escala urbana mucho más tranquila.","La postal de Copacabana no se entiende solo desde la arena: su historia también está en túneles, edificios, bares y calles interiores."],"carioca":["Camina temprano por la orla y observa cómo la playa funciona como gimnasio al aire libre.","Entra en una padaria de barrio: desayuno, café y vida cotidiana cuentan tanto como una atracción famosa.","No te quedes únicamente en Avenida Atlântica; cruza hacia las calles interiores.","Prueba una vuelta corta por Bairro Peixoto para ver el contraste con la orla.","Mira un partido informal, futevôlei o vóley sin convertir cada momento en una fotografía.","Compra agua de coco, conversa y observa el ritmo del barrio.","Usa el Metro cuando tenga sentido; Copacabana no necesita vivirse siempre en automóvil.","Mira arriba: el patrimonio del barrio muchas veces está varios pisos sobre tu cabeza.","Al final de la tarde, camina sin una lista rígida y deja espacio para el barrio.","Recuerda que aquí vive gente: la postal también es casa, trabajo y rutina."],"routes":[{"time":"1 h","title":"Copacabana esencial","stops":["Calçadão","Drummond","Posto 6"],"note":"Una primera lectura rápida del extremo sur y de la imagen clásica."},{"time":"3 h","title":"Historia + postal","stops":["Forte","Drummond","Calçadão","arquitectura de la orla"],"note":"Para primera visita con interés histórico y fotográfico."},{"time":"½ día","title":"Mira arriba","stops":["Copacabana Palace exterior","Lido","Art Déco","calles interiores","Bairro Peixoto"],"note":"La Copacabana que muchos turistas atraviesan sin mirar."},{"time":"½ día","title":"Hazlo como un carioca","stops":["padaria","playa","deporte","comida sencilla","paseo interior"],"note":"Menos monumentos, más ritmo cotidiano."},{"time":"60 min","title":"Reel en 60 minutos","stops":["ondas del calçadão","curva de la playa","Drummond","Posto 6"],"note":"Pensada para fotografía y video corto."}],"profiles":[["👶","Con bebé","Sombra, distancias cortas, baño, aire acondicionado y plan de siesta."],["👨‍👩‍👧","Familia","Playa + comida sencilla + actividades cortas sin sobrecargar el día."],["🧑‍🎓","Adolescentes","Deporte, fotos, comida, playa y experiencias que no se sientan como una clase."],["👵","Mayores","El motor pregunta movilidad y ritmo; la edad por sí sola no decide."],["❤️","Pareja","Atardecer, paseo, gastronomía y experiencias íntimas sin asumir que romántico significa caro."],["🧍","Solo","Flexibilidad, vida local y decisiones según hora y ubicación."],["♿","Movilidad reducida","Solo recomendamos como accesible aquello que tenga datos suficientemente verificados."],["🐶","Mascota","Política de mascotas y espacios compatibles como filtros, no como suposiciones."]]};
